    public void handleKey(javafx.scene.input.KeyEvent e){switch(e.getCode()){
        case E->openEcho(selectedRoom);
        case PAGE_UP->map.changeFloor(1);case PAGE_DOWN->map.changeFloor(-1);case HOME->{if(state!=null)map.center(state.actor(client.slot).roomId);}case P->openPanel("ЛИЧНЫЕ РЕШЕНИЯ");case K->openPanel("СДЕРЖИВАНИЕ");case H->openPanel("РЕШЕНИЯ");case I->openPanel("ИНВЕНТАРЬ");case J->openPanel("РАССЛЕДОВАНИЕ");case M->openPanel("РЕГИОН");case V->showVote();case F->openPanel("ВЗАИМОДЕЙСТВИЕ");
        case ESCAPE->{if(modal!=null)closePanel();else openPanel("МЕНЮ");e.consume();}
        case TAB->{if(modal==null){var layers=List.of("СТРУКТУРА","БИОЛОГИЯ","ПИТАНИЕ","ВОЗДУХ");map.setLayer(layers.get((layers.indexOf(map.layer())+1)%layers.size()));e.consume();}}
        case SPACE->{if(modal==null){client.send("STOP",Map.of());e.consume();}}default->{}
    }}
    private void top(String title,Label value,int x,int w){put(label(title,9,MUTED),x,7,w,15);put(value,x,24,w,30);}
