    public void render(){map.render(motion);if(state!=null){long now=System.nanoTime();double since=(now-client.receivedAt)/1e9;chrome.timer(state.phase==Phase.ACTION?Math.max(0,state.remaining-since):Math.max(0,state.voteRemaining-since));if(state.phase==Phase.VOTING&&autoVote&&shownVoteCycle!=state.cycle&&now-voteObservedAt>1_500_000_000L){shownVoteCycle=state.cycle;showVote();}phaseOverlay.render(modalKind.equals("ГОЛОСОВАНИЕ"),motion);}}
    public void update(Campaign s){
        boolean becameEcho=s.actor(client.slot).life.equals("ECHO")&&(state==null||!state.actor(client.slot).life.equals("ECHO"));
        audio.update(s,client.slot);
        if(state!=null&&state.phase==Phase.GAME_OVER&&s.phase!=Phase.GAME_OVER)closePanel();state=s;map.setState(s,client.slot);chrome.draw(s,selected);body.draw(s.actor(selected));miniRegion.update(s);phaseOverlay.update(s);phaseOverlay.own=client.slot;phaseOverlay.status=client.error;
        if(s.phase==Phase.VOTING&&pendingVoteCycle!=s.cycle){pendingVoteCycle=s.cycle;voteObservedAt=System.nanoTime();}
        if(s.phase==Phase.GAME_OVER&&!modalKind.equals("КОНЕЦ"))openPanel("КОНЕЦ");
        if(modalKind.equals("ГОЛОСОВАНИЕ")){if(s.phase!=Phase.VOTING)closePanel();else fillVote();}
        if(modalKind.equals("ЛОББИ"))fillLobby();
        if(inventoryPanel!=null)inventoryPanel.update(s);
        if(continueButton!=null){continueButton.setDisable(s.chapterReady.contains(client.slot));continueButton.setText("ЭКСПЕДИЦИЯ / ГОТОВЫ "+s.chapterReady.size()+" / "+s.actors.stream().filter(a->a.connected&&!a.life.equals("DORMANT")).count()+" — "+(s.chapterReady.contains(client.slot)?"ЖДЁМ ОСТАЛЬНЫХ":"ПОДТВЕРДИТЬ ПРОДОЛЖЕНИЕ"));}if(decisionHistory!=null)decisionHistory.update(s);if(defensePanel!=null)defensePanel.update(s);
        if(systemsPanel!=null)systemsPanel.update(s);if(evidencePanel!=null)evidencePanel.update(s);
        if(echoPanel!=null)echoPanel.update(s);
        if(becameEcho&&s.phase==Phase.ACTION)openEcho("");
    }
