    private void cast(String id){if(state.phase!=Phase.VOTING){client.error="Голосовать можно после окончания минуты. Сейчас показаны предложения.";return;}client.send("VOTE",Map.of("cycle",state.cycle,"option",id));}
    private void context(String target,javafx.scene.input.MouseEvent event){if(state==null)return;selectedRoom=target;var menu=new ContextMenu();
        if(state.actor(client.slot).life.equals("ECHO")){echoMenu(target).show(this,event.getScreenX(),event.getScreenY());return;}
        if(target.startsWith("CONTACT:")){combatMenu(target.substring(8)).show(this,event.getScreenX(),event.getScreenY());return;}
        if(WorldObjects.get(state,target)!=null){objectMenu(target).show(this,event.getScreenX(),event.getScreenY());return;}
        if(state.doors.containsKey(target)){var d=state.doors.get(target);var info=new MenuItem(d.id+" / "+d.status+" / "+d.a+" ↔ "+d.b);info.setDisable(true);menu.getItems().add(info);for(String a:List.of("OPEN","CLOSE")){var item=new MenuItem(a.equals("OPEN")?"Открыть":"Закрыть");item.setOnAction(e->client.send("USE_DOOR",Map.of("target",target,"action",a)));menu.getItems().add(item);}}
        else for(String action:roomActions(target)){var item=new MenuItem(GameEngine.actionTitle(action));item.setOnAction(e->client.send("INTERACT",Map.of("target",target,"action",action)));menu.getItems().add(item);}
        menu.show(this,event.getScreenX(),event.getScreenY());}
    private ContextMenu combatMenu(String id){var menu=new ContextMenu();var c=state.contacts.get(id);for(var w:DefenseRules.WEAPONS){String why=DefenseRules.reason(state,state.actor(client.slot),c,w);var b=new MenuItem(w.name()+" / зарядов "+DefenseRules.count(state.actor(client.slot),w.ammunition())+" / дальность "+w.range()+(why.isEmpty()?"":" — "+why));b.setDisable(!why.isEmpty());b.setOnAction(ev->{client.error="";client.send("FIRE",Map.of("target",id,"weapon",w.id()));});menu.getItems().add(b);}return menu;}
    private void openEcho(String room){openPanel("ТЕРМИНАЛ ЭХО");if(echoPanel!=null)echoPanel.select(room);}
    private ContextMenu echoMenu(String target){
        var menu=new ContextMenu();String room=target;var fixture=WorldObjects.get(state,target);if(fixture!=null)room=fixture.room();if(target.startsWith("CONTACT:")&&state.contacts.containsKey(target.substring(8)))room=state.contacts.get(target.substring(8)).roomId;
        if(state.doors.containsKey(target)){var door=state.doors.get(target);room=EchoRules.coveredRooms(state,state.actor(client.slot)).contains(door.a)?door.a:door.b;addEchoChoice(menu,"WATCH",room);for(String action:List.of("OPEN","CLOSE"))addEchoChoice(menu,action,target);}
        else for(String action:List.of("WATCH","MARK","DECOY"))addEchoChoice(menu,action,room);
        String focus=room;var panel=new MenuItem("Терминал Эхо / E");panel.setOnAction(e->openEcho(focus));menu.getItems().add(panel);return menu;
    }
    private void addEchoChoice(ContextMenu menu,String action,String target){var offer=EchoRules.offer(state,state.actor(client.slot),action,target);var item=new MenuItem(offer.title()+" → "+target+(offer.power()>0?" / −"+offer.power()+"%":"")+(offer.enabled()?"":" — "+offer.reason()));item.setDisable(!offer.enabled());item.setOnAction(e->{client.error="";client.send("ECHO_ACTION",Map.of("target",target,"action",action));if(action.equals("WATCH"))map.center(target);});menu.getItems().add(item);}
    private ContextMenu objectMenu(String id){var f=WorldObjects.get(state,id);var menu=new ContextMenu();var header=new MenuItem(f.name()+" / "+f.room());header.setDisable(true);menu.getItems().add(header);
        for(var offer:WorldObjects.offers(state,state.actor(client.slot),f)){String cost=offer.cost().isEmpty()?"":(" / "+costTitle(offer.cost()));var item=new MenuItem(offer.title()+" / "+(int)offer.seconds()+" с"+cost+(offer.enabled()?"":" — "+offer.reason()));item.setDisable(!offer.enabled());item.setOnAction(e->{closePanel();client.error="";client.send("USE_OBJECT",Map.of("target",id,"action",offer.action()));});menu.getItems().add(item);var detail=new MenuItem(offer.description());detail.setDisable(true);menu.getItems().add(detail);}return menu;}
    private List<String> roomActions(String room){var actions=new ArrayList<>(List.of("SCAN","LURE"));switch(room){case "A2"->actions.add("CAPSULES");case "B2"->actions.add("REPAIR");case "B3"->actions.add("FILTER");case "B6"->actions.add("ARCHIVE");case "B7"->actions.add("SAMPLE");case "B8"->actions.add("LOOT");case "B1"->actions.add("POWER");case "C1"->actions.add("DRONE");}return actions;}
