    public void dispose(){audio.close();}
    public String panelKind(){return modalKind;}
    public String audioStatus(){return audio.status;}
    private double audioLevel(String key,double fallback){try{double value=Double.parseDouble(settings.getProperty(key,Double.toString(fallback)));return Double.isFinite(value)?Math.clamp(value,0,1):fallback;}catch(NumberFormatException e){return fallback;}}
    private static String lifeTitle(String life){return switch(life){case "ALIVE"->"В НОРМЕ";case "CRITICAL"->"КРИТИЧЕСКИ";case "ECHO"->"ЭХО";default->life;};}
    static String costTitle(Map<String,Integer> cost){if(cost.isEmpty())return "нет затрат";return cost.entrySet().stream().map(e->switch(e.getKey()){case "fuel"->"топливо";case "parts"->"детали";case "filters"->"фильтры";case "batteries"->"батареи";case "food"->"пайки";case "meds"->"медикаменты";case "ammo"->"патроны";default->e.getKey();}+" ×"+e.getValue()).collect(java.util.stream.Collectors.joining(", "));}
    private static String resources(Campaign s){return "ТОПЛИВО "+s.supplies.get("fuel")+"  ДЕТАЛИ "+s.supplies.get("parts")+"  ФИЛЬТРЫ "+s.supplies.get("filters")+"  ВОДА "+Math.round(s.water);}
    public static String formatTime(double seconds){int t=(int)Math.ceil(Math.max(0,seconds));return String.format("%02d:%02d",t/60,t%60);}
    public static Label label(String text,int size,Color c){var l=new Label(text);l.setFont(ReferenceAssets.text(size));l.setStyle("-fx-font-size:"+size+"px;");l.setTextFill(c);return l;}
    public static Button button(String text,Runnable action){var b=new Button(text);b.setOnAction(e->action.run());return b;}
    private void put(Node n,double x,double y,double w,double h){place(this,n,x,y,w,h);}
    public static void place(Pane p,Node n,double x,double y,double w,double h){n.setLayoutX(x);n.setLayoutY(y);if(n instanceof Region r){r.setPrefSize(w,h);r.resize(w,h);}p.getChildren().add(n);}
    private static void drawPortrait(Canvas c,Color accent,int index){var g=c.getGraphicsContext2D();g.setFill(BG);g.fillRect(0,0,57,81);g.setStroke(BORDER);g.strokeRect(0,0,57,81);g.setFill(Color.web("#203e33"));g.fillOval(15,12,28,35);g.fillPolygon(new double[]{5,14,42,53},new double[]{78,48,48,78},4);g.setStroke(accent.deriveColor(0,.4,.6,.7));g.strokeOval(17,14,24,31);g.strokeLine(22,27,25,27);g.strokeLine(33,27,36,27);g.strokeLine(25,37,33,37);g.setFill(MUTED);g.setFont(Font.font("Consolas",8));g.fillText(new String[]{"A-17","B-04","C-31"}[index],14,72);}
